import { useState, FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton } from '@jinx-ui/react';

export interface ProfileSettings {
  name: string;
  language: string;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  initialValue?: ProfileSettings;
  onSave: (settings: ProfileSettings) => void;
}

export default function ProfileSettingsForm({ initialValue, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialValue?.name ?? '');
  const [language, setLanguage] = useState(initialValue?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(initialValue?.emailNotifications ?? true);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name: name.trim(), language, emailNotifications });
  };

  return (
    <form
      onSubmit={submit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxInputField
        label="Имя"
        required
        value={name}
        onChange={(event) => setName(event.target.value)}
        placeholder="Как к вам обращаться"
        errorText={name.length > 0 && name.trim().length === 0 ? 'Укажите имя' : undefined}
      />

      <JxSelect
        label="Язык интерфейса"
        options={[
          { value: 'ru', label: 'Русский' },
          { value: 'en', label: 'English' },
        ]}
        value={language}
        onValueChange={setLanguage}
      />

      <JxSwitch
        label="Уведомления на почту"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />

      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        <JxButton type="submit" variant="primary" disabled={name.trim().length === 0}>
          Сохранить
        </JxButton>
      </div>
    </form>
  );
}

